import json
import re

INT_RE = re.compile(r"^-?\d+$")


def _to_int(v):
    if isinstance(v, bool):                       # bool est une sous-classe de int en Python
        raise ValueError
    if isinstance(v, int):
        return v
    if isinstance(v, str) and INT_RE.match(v.strip()):
        return int(v.strip())
    raise ValueError


def _to_event(v):
    if isinstance(v, str) and v.strip():
        return v.strip()
    raise ValueError


def _to_value(v):
    if v is None:
        return None
    if isinstance(v, bool):
        raise ValueError
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        return float(v.strip())                   # lève ValueError si ce n'est pas un nombre
    raise ValueError


def parse_events(ndjson_text):
    records, errors = [], []
    for line_no, line in enumerate(ndjson_text.split("\n"), start=1):   # numéro de ligne physique
        if not line.strip():
            continue                              # ligne vide : ni record ni erreur
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            errors.append({"line": line_no, "reason": "invalid_json"})
            continue
        if not isinstance(obj, dict):
            errors.append({"line": line_no, "reason": "not_an_object"})
            continue
        missing = next((f for f in ("id", "event") if obj.get(f) is None), None)
        if missing:
            errors.append({"line": line_no, "reason": f"missing_field:{missing}"})
            continue
        out = {}
        for field, convert in (("id", _to_int), ("event", _to_event), ("value", _to_value)):
            try:
                out[field] = convert(obj.get(field))
            except ValueError:
                errors.append({"line": line_no, "reason": f"invalid_field:{field}"})
                break
        else:
            records.append(out)
    return records, errors
